package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import java.util.Date;
import java.util.Iterator;
import java.util.List;
import java.util.TimeZone;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.event.SeriesChangeEvent;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesException;
import org.jfree.data.time.Second;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;

public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        // Add some data points
        series.add(new TimeSeriesDataItem(new Second(new java.util.Date(1000L)), 10.0));
        series.add(new TimeSeriesDataItem(new Second(new java.util.Date(2000L)), 20.0));
        series.add(new TimeSeriesDataItem(new Second(new java.util.Date(3000L)), 30.0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopy_StartNegative() throws CloneNotSupportedException {
        series.createCopy(-1, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopy_EndLessThanStart() throws CloneNotSupportedException {
        series.createCopy(2, 1);
    }

    @Test
    public void testCreateCopy_ValidRange() throws CloneNotSupportedException {
        // Test copying indices 0 to 1
        TimeSeries copy = series.createCopy(0, 1);

        assertNotNull(copy);
        assertNotSame(series, copy);
        assertEquals(series.getKey(), copy.getKey());
        assertEquals(2, copy.getItemCount());

        // Verify data integrity
        assertEquals(series.getValue(0), copy.getValue(0));
        assertEquals(series.getValue(1), copy.getValue(1));
        // Verify the item in copy is a different object (cloned)
        assertNotSame(series.getDataItem(0), copy.getDataItem(0));
    }

    @Test
    public void testCreateCopy_SingleElement() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(1, 1);
        assertEquals(1, copy.getItemCount());
        assertEquals(series.getValue(1), copy.getValue(1));
    }

    @Test
    public void testCreateCopy_FullRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, series.getItemCount() - 1);
        assertEquals(series.getItemCount(), copy.getItemCount());
    }

    @Test
    public void testCreateCopy_EmptySeries() throws CloneNotSupportedException {
        TimeSeries emptySeries = new TimeSeries("Empty");
        TimeSeries copy = emptySeries.createCopy(0, 0);

        // Note: The implementation checks if (this.data.size() > 0). 
        // If empty, it returns a clone with an empty list.
        assertEquals(0, copy.getItemCount());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testCreateCopy_IndexOutOfBounds() throws CloneNotSupportedException {
        // This will trigger an exception in the loop when accessing this.data.get(index)
        series.createCopy(0, 5);
    }
}
